package nro.models.event.trungthu2026;
import java.sql.*;import java.util.*;import java.nio.file.*;import com.google.gson.*;import nro.models.vip.*;import nro.models.data.LocalManager;import nro.models.server.Manager;import nro.models.player_system.Template.*;import nro.models.player.*;import nro.models.item.Item;import nro.models.skill.*;
/** Integration tests restricted to the disposable QA database. */
public class ToriVipTest {
 static int checks;static final int BASE=2026102600;static Connection c;static JsonObject defaults;static long rev=1000;
 static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS: "+label);}
 static long value(String sql)throws Exception{try(var s=c.createStatement();var r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
 static void load(JsonObject data)throws Exception{try(var q=c.prepareStatement("UPDATE tori_vip_config SET config=?,revision=? WHERE id=1")){q.setString(1,data.toString());q.setLong(2,++rev);q.executeUpdate();}ToriVipConfig.reload(c);}
 static TrungThuRuntimeTest.User user(int n,int slots,int funds)throws Exception{var p=new TrungThuRuntimeTest.User(BASE+n);p.getSession().userId=BASE+n;p.getSession().vnd=funds;for(int i=0;i<slots;i++)p.inventory.itemsBag.add(new Item());try(var q=c.prepareStatement("INSERT INTO account(id,username,is_admin,vnd,last_time_login,last_time_logout) VALUES(?,?,0,?,'2000-01-01','2000-01-02')")){q.setInt(1,BASE+n);q.setString(2,"tori_qa_"+n);q.setInt(3,funds);q.executeUpdate();}try(var q=c.prepareStatement("INSERT INTO player(id,name,account_id,gender,data_vip,items_bag,data_inventory) VALUES(?,?,?,0,'[0,0,false,false,false,0,0,0]','[]','[0,0,0,0,0]')")){q.setInt(1,BASE+n);q.setString(2,p.name);q.setInt(3,BASE+n);q.executeUpdate();}return p;}
 static boolean buy(Player p,int level){var r=ToriVipService.buy(p,level,rev);System.out.println(r.message());return r.success();}
 static long balance(Player p)throws Exception{return value("SELECT vnd FROM account WHERE id="+p.getSession().userId);}
 public static void main(String[] args)throws Exception{try{c=LocalManager.getConnection();check("nro_panel_qa_20261013".equals(c.getCatalog()),"QA guard");try(var s=c.createStatement()){for(String sql:Files.readString(Path.of(args[0],"web/toribot_schema.sql")).split(";"))if(!sql.isBlank())s.execute(sql);for(String col:List.of("data_vip","pet")){try(var r=s.executeQuery("SHOW COLUMNS FROM player LIKE '"+col+"'")){if(!r.next())try(var a=c.createStatement()){a.execute("ALTER TABLE player ADD "+col+" LONGTEXT");}}}s.execute("DELETE FROM player WHERE id BETWEEN "+BASE+" AND "+(BASE+99));s.execute("DELETE FROM account WHERE id BETWEEN "+BASE+" AND "+(BASE+99));try(var r=s.executeQuery("SELECT * FROM item_template ORDER BY id")){while(r.next())Manager.ITEM_TEMPLATES.add(new ItemTemplate((short)r.getInt("id"),(byte)r.getInt("TYPE"),(byte)r.getInt("gender"),r.getString("NAME"),r.getString("description"),(short)r.getInt("icon_id"),(short)r.getInt("part"),false,r.getInt("power_require")));}try(var r=s.executeQuery("SELECT * FROM item_option_template ORDER BY id")){while(r.next())Manager.ITEM_OPTION_TEMPLATES.add(new ItemOptionTemplate(r.getInt("id"),r.getString("NAME"),0));}}
 for(int i=0;i<3;i++)Manager.NCLASS.add(new NClass());for(int id:new int[]{Skill.DRAGON,Skill.DEMON,Skill.GALICK}){SkillTemplate t=new SkillTemplate();t.id=(byte)id;t.name="QA";Skill skill=new Skill();skill.template=t;skill.point=1;t.skillss.add(skill);Manager.NCLASS.get(0).skillTemplatess.add(t);}
 defaults=new JsonParser().parse(Files.readString(Path.of(args[0],"web/toribot_defaults.json"))).getAsJsonObject();load(defaults);
 for(int level=1;level<=4;level++){var p=user(level,100,1000000);check(buy(p,level),"tier "+level+" buys actual rewards");check(p.vip==level&&p.vipPurchaseCount==1&&balance(p)==1000000-level*50000&&p.getSession().vnd==balance(p),"tier debit and VIP agree");check(p.inventory.itemsBag.stream().filter(Item::isNotNullItem).count()>=6,"all rewards reach bag");check(level==4?p.pet==null:p.pet!=null,"pet reward follows configured tier");check(value("SELECT JSON_EXTRACT(data_vip,'$[7]') FROM player WHERE id="+p.id)==1,"VIP count persisted");if(level<4)check(value("SELECT JSON_LENGTH(pet) FROM player WHERE id="+p.id)==4,"new pet persisted atomically");check(ToriVipService.expBonus(p)==300,"configured EXP active");var stale=new TrungThuRuntimeTest.User((int)p.id);stale.getSession().userId=p.getSession().userId;check(!buy(stale,level)&&balance(p)==1000000-level*50000,"stale player cannot overwrite purchase count");}
 var poor=user(10,100,1);check(!buy(poor,1)&&balance(poor)==1&&poor.pet==null&&poor.vip==0,"insufficient funds grants nothing");var full=user(11,1,1000000);check(!buy(full,1)&&balance(full)==1000000&&full.pet==null&&full.vip==0&&!full.inventory.itemsBag.get(0).isNotNullItem(),"full bag restores partial rewards and pet");var failed=user(12,100,1000000);try(var s=c.createStatement()){s.execute("CREATE TRIGGER qa_tori_failure BEFORE INSERT ON tori_vip_purchase FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Expected QA error'");}try{check(!buy(failed,1)&&balance(failed)==1000000&&failed.vip==0&&failed.pet==null&&failed.inventory.itemsBag.stream().noneMatch(Item::isNotNullItem),"audit SQL failure rolls back debit bag VIP pet");}finally{try(var s=c.createStatement()){s.execute("DROP TRIGGER qa_tori_failure");}}check(buy(failed,1),"retry after storage recovery");Pet old=failed.pet;check(buy(failed,2)&&failed.pet==old&&failed.vip==2,"existing pet preserved on upgrade");check(buy(failed,1)&&failed.vip==2,"lower tier keeps active higher VIP");check(buy(failed,1)&&!buy(failed,1)&&failed.vipPurchaseCount==4,"season purchase cap enforced");
 var cfg=defaults.deepCopy();cfg.addProperty("enabled",false);load(cfg);check(!buy(failed,1)&&ToriVipService.expBonus(failed)==300,"pause sales preserves bought EXP");cfg.addProperty("enabled",true);cfg.addProperty("starts_at","2027-01-01T00:00:00");cfg.addProperty("ends_at","2027-12-01T00:00:00");load(cfg);check(!buy(poor,1)&&ToriVipService.expBonus(failed)==0,"outside dates gates sales and seasonal EXP");load(defaults);check(!ToriVipService.buy(poor,1,rev-1).success(),"stale config rejected");failed.timevip=1;check(ToriVipService.expBonus(failed)==0,"expired VIP no bonus");cfg=defaults.deepCopy();cfg.addProperty("season_key","qa_next");load(cfg);ToriVipService.syncSeason(failed);check(failed.vip==0&&failed.vipPurchaseCount==0&&failed.timevip==0,"new season resets only VIP fields");load(defaults);check(ToriVipConfig.get().tiers().size()==4,"all default tiers valid");var npc=new nro.models.npc_list.ToriBot(0,1,0,0,74,0){@Override public boolean canOpenNpc(Player p){return true;}};var cancelled=user(20,100,1000000);npc.openBaseMenu(cancelled);npc.confirmMenu(cancelled,0);check(cancelled.idMark.getIndexMenu()==11,"NPC opens VIP confirmation");npc.confirmMenu(cancelled,1);check(balance(cancelled)==1000000&&cancelled.vip==0,"closing confirmation never purchases");npc.confirmMenu(cancelled,0);check(balance(cancelled)==1000000,"consumed quote cannot replay");npc.openBaseMenu(cancelled);npc.confirmMenu(cancelled,0);load(defaults);npc.confirmMenu(cancelled,0);check(balance(cancelled)==1000000,"price changed after quote rejects purchase");
var legacy=user(21,100,1000000);legacy.vipPurchaseCount=1;try(var s=c.createStatement()){s.execute("UPDATE player SET data_vip='[0,0,false,false,false,1,0,1,\"\",300]' WHERE id="+legacy.id);}check(buy(legacy,1)&&legacy.vipPurchaseCount==2,"legacy empty season preserves old purchase count");
var custom=defaults.deepCopy();custom.getAsJsonArray("tiers").get(0).getAsJsonObject().add("items",new JsonArray());custom.getAsJsonArray("tiers").get(0).getAsJsonObject().addProperty("normal_pet",false);custom.getAsJsonArray("tiers").get(0).getAsJsonObject().addProperty("exp_bonus",25);load(custom);var pure=user(22,0,1000000);check(buy(pure,1)&&ToriVipService.expBonus(pure)==25&&pure.pet==null,"VIP-only package works with edited EXP and no items");custom.addProperty("season_key","new_online");load(custom);check(ToriVipService.expBonus(pure)==0,"online previous-season player loses seasonal EXP immediately");load(defaults);System.out.println("PASS: "+checks+" Tori VIP checks");
 }finally{if(c!=null){try(var s=c.createStatement()){s.execute("DROP TRIGGER IF EXISTS qa_tori_failure");s.execute("DELETE FROM tori_vip_purchase WHERE player_id BETWEEN "+BASE+" AND "+(BASE+99));s.execute("DELETE FROM player WHERE id BETWEEN "+BASE+" AND "+(BASE+99));s.execute("DELETE FROM account WHERE id BETWEEN "+BASE+" AND "+(BASE+99));}if(defaults!=null)load(defaults);c.close();}LocalManager.close();}System.exit(0);}
}